      id: "ts-25", number: 25, title: "Real Developer Typing Workflows", subtitle: "Commenting, debugging, refactoring, and navigation", difficulty: "Intermediate", estimatedMinutes: 50, xpReward: 60, prerequisites: [], learningObjectives: ["Type through real dev workflows", "Handle debugging patterns", "Master refactoring typing"], partLabel: "Part 3: Coding Typing Systems",
      sections: [{"id":"s1","title":"Developer Workflow Typing","whyItMatters":"Real development isn't just typing code — it's a cycle of reading, writing, debugging, and refactoring.","content":"**Workflow 1 — Adding a Feature:**\n1. Read existing code (comprehension)\n2. Plan changes (mental typing)\n3. Write new functions\n4. Add comments\n5. Test and debug\n\n**Workflow 2 — Debugging:**\n- Add console.log statements\n- Type breakpoint conditions\n- Read stack traces\n- Fix and retype\n\n**Workflow 3 — Refactoring:**\n- Extract functions\n- Rename variables\n- Reorganize imports\n- Type updated type signatures\n\n**Typing in Comments:**\n- // single line: Left pinkie, / /\n- /* block */: / then *\n- JSDoc: /** + Enter\n\n**Typing for Code Review:**\n- Reading code is also typing practice\n- Mental typing reinforces patterns","codeExamples":[{"id":"ex1","title":"Dev Workflow","description":"Simulate a real development cycle","code":{"typing-speed":"// TODO: implement user authentication\n// Step 1: validate input\nfunction validateInput(email, password) {\n    if (!email || !password) {\n        throw new Error('Missing required fields');\n    }\n    return { email, password };\n}\n// Step 2: hash password\nconst bcrypt = require('bcrypt');\nconst salt = await bcrypt.genSalt(10);"},"explanation":"This simulates a real coding workflow with comments, functions, and imports."}]}],
      quiz: { questions: [{"id":"q1","type":"mcq","question":"What key combination produces // for comments?","options":["Ctrl+/","Alt+/","Shift+/","Two forward slashes"],"correctAnswer":"Two forward slashes","explanation":"// is two forward slash characters typed with right pinkie.","difficulty":2}], passingScore: 70 },
      cheatSheet: [{"label":"//","value":"Single-line comment"},{"label":"/** */","value":"JSDoc comment block"},{"label":"Refactoring","value":"Restructure code without changing behavior"}]
